update public.count_sessions set status = 'counting', created_at = now() - interval '9 hours' where org_id = '10000000-0000-4000-8000-000000000001';
do $$
declare
  s record;
  t uuid;
  supplier_ids uuid[];
  member_ids uuid[] := array['00000000-0000-4000-8000-000000000100'::uuid, '00000000-0000-4000-8000-000000000101'::uuid, '00000000-0000-4000-8000-000000000102'::uuid, '00000000-0000-4000-8000-000000000103'::uuid, '00000000-0000-4000-8000-000000000104'::uuid, '00000000-0000-4000-8000-000000000105'::uuid, '00000000-0000-4000-8000-000000000106'::uuid, '00000000-0000-4000-8000-000000000107'::uuid, '00000000-0000-4000-8000-000000000108'::uuid, '00000000-0000-4000-8000-000000000109'::uuid, '00000000-0000-4000-8000-000000000110'::uuid, '00000000-0000-4000-8000-000000000111'::uuid];
  i int;
begin
  for s in select id, code from public.count_sessions where org_id = '10000000-0000-4000-8000-000000000001' order by code loop
    select array_agg(id order by name) into supplier_ids from public.suppliers where org_id = '10000000-0000-4000-8000-000000000001';
    for i in 1..6 loop
      insert into public.teams (session_id, org_id, name)
      values (s.id, '10000000-0000-4000-8000-000000000001', (array['Pasillo A', 'Pasillo B', 'Pasillo C', 'Cámara fría', 'Mezzanine', 'Patio de carga'])[i]) returning id into t;
      insert into public.team_members (team_id, user_id, org_id)
      values (t, member_ids[i * 2 - 1], '10000000-0000-4000-8000-000000000001'), (t, member_ids[i * 2], '10000000-0000-4000-8000-000000000001');
      insert into public.team_suppliers (team_id, supplier_id, session_id, org_id)
      select t, sid, s.id, '10000000-0000-4000-8000-000000000001'
      from unnest(supplier_ids) with ordinality u(sid, n)
      where (n - 1) % 6 = i - 1
        and (s.code = 1 or n <= array_length(supplier_ids, 1) - 2);
    end loop;

    -- Count events: every product of the first session, about 60% of the second.
    insert into public.counts (product_id, pallets, layers, boxes, units, expires_on, condition, counted_by, created_at)
    select
      p.id,
      1,
      1,
      greatest(0, floor(p.system_qty / p.units_per_box)::int + case when r < 0.10 then -2 when r < 0.16 then 1 else 0 end),
      (p.system_qty - floor(p.system_qty / p.units_per_box) * p.units_per_box)::int,
      current_date + (30 + floor(random() * 400))::int,
      case when random() < 0.03 then 'averiado'::public.product_condition else 'bueno' end,
      tm.user_id,
      now() - (random() * interval '8 hours')
    from public.session_products p
    cross join lateral (select random() as r) rr
    join public.team_suppliers ts on ts.session_id = p.session_id and ts.supplier_id = p.supplier_id
    join lateral (select user_id from public.team_members where team_id = ts.team_id limit 1) tm on true
    where p.session_id = s.id and (s.code = 1 or random() < 0.62);
  end loop;

  update public.count_sessions set status = 'closed' where org_id = '10000000-0000-4000-8000-000000000001' and code = 1;
end $$;
update public.session_products set recount_requested = true where id in (select id from public.session_product_status where status = 'faltante' and difference_value < -40 limit 6);
reset role;
